(defn receipt-transition [state event]
  ;; Proposed pure rule; persistence must serialize the decision.
  (let [allowed {:pending #{:settled :refund-pending}
                 :refund-pending #{:refunded}}
        target (:target event)]
    (cond
      (not (true? (:verified event)))
      {:error :untrusted-event}
      (not (contains? (get allowed state #{}) target))
      {:error :illegal-transition}
      :else {:next-state target
             :event-id (:event-id event)})))

def read(self, owner, now):
    if owner != self.owner:
        raise PermissionError("account scope")
    integer(now)
    with self.lock:
        snapshot = self.snapshot
        active_incident = now < self.incident_until
        if snapshot is None:
            return {"state": "unknown", "balance_cents": None,
                    "incident": active_incident, "may_resend": False}
        version, cents, observed, valid_until = snapshot
        if now < observed:
            return {"state": "unknown", "balance_cents": None,
                    "incident": active_incident, "may_resend": False}
        fresh = now < valid_until
        return {"state": "fresh" if fresh else "stale",
                "balance_cents": cents, "version": version,
                "as_of": observed, "incident": active_incident,
                "may_resend": False}

